            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var ss = ds.seasons || [];
            var rounds = ds.rounds || [];
            var sEl = document.getElementById('seasonText');
            if (sEl) { sEl.innerHTML = ss.length ? this._seasonHtml(ds, ss[ss.length - 1]) : this._t('sem_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.classList.remove('ck2191-warn');
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey !== 'ok') { fbEl.classList.add('ck2191-warn'); }
                }
            }
        }

        _seasonHtml(ds, s) {
            var v = {
                deliv: String(Math.round(s.I * 100)), water: String(Math.round(s.W * 100)), drip: String(s.drip), tol: String(Math.round(s.ts * 100)),
                yld: this._fmt1(s.yld), planted: String(s.planted), south: String(s.sha), ys: this._fmt1(s.ys),
                prem: this._fmtM(s.prem), pay: this._fmtM(s.pay), margin: this._fmtM(s.margin), cash: this._fmtM(s.cash),
                well: String(Math.round(s.well)), interest: this._fmtM(s.interest)
            };
            var html = this._t('sem_body', v);
            if (s.q === 3) { html += '<span class="ck2191-reveal">' + this._t('s_heat') + '</span>'; }
            if (s.pay > 0) { html += '<span class="ck2191-reveal">' + this._t('s_payout', v) + '</span>'; }
            if (s.well > 0) { html += '<span class="ck2191-reveal">' + this._t('s_well', v) + '</span>'; }
            if (s.leyRejected) { html += '<span class="ck2191-reveal">' + this._t('s_ley_rejected') + '</span>'; }
            if (s.interest > 0) { html += '<span class="ck2191-reveal">' + this._t('s_interest', v) + '</span>'; }
            if (ds.capKey) { html += '<span class="ck2191-reveal">' + this._t(ds.capKey) + '</span>'; }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: String(Math.round(r.pts * 10) / 10) };
            var html = '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
            if (r.period === 4 && ds.netWorth !== null && ds.netWorth !== undefined) {
                html += ' ' + this._t('nw_line', { nw: this._fmtM(ds.netWorth) });
            }
            return html;
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var var1 = this._readSelect('r1_var', VARS);
                var lease1 = this._readSelect('r1_lease', LEASES);
                var ins1 = this._readSelect('r1_ins', INS);
                if (!var1 || !lease1 || !ins1) { return warn('warn_r1'); }
                decisions.round1 = { mix: var1, lease: lease1, ins: ins1 };
                return true;
            }
            if (period === 2) {
                var capex2 = this._readSelect('r2_capex', CAPEX2);
                var water2 = this._readSelect('r2_water', WATER);
                var ins2 = this._readSelect('r2_ins', INS);
                if (!capex2 || !water2 || !ins2) { return warn('warn_r2'); }
                decisions.round2 = { capex: capex2, water: water2, ins: ins2 };
                return true;
            }
            if (period === 3) {
                var capex3 = this._readSelect('r3_capex', CAPEX3);
                var var3 = this._readSelect('r3_var', VARS);
                var ins3 = this._readSelect('r3_ins', INS);
                if (!capex3 || !var3 || !ins3) { return warn('warn_r3'); }
                decisions.round3 = { capex: capex3, mix: var3, ins: ins3 };
                return true;
            }
            if (period === 4) {
                var lease4 = this._readSelect('r4_lease', LEASES);
                var shares4 = this._readSelect('r4_shares', SHARES);
                var ins4 = this._readSelect('r4_ins', INS);
                if (!lease4 || !shares4 || !ins4) { return warn('warn_r4'); }
                decisions.round4 = { lease: lease4, shares: shares4, ins: ins4 };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every carried quantity is rebuilt from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var seasons = [];
            var cash = C.CASH0;
            var minCash = C.CASH0;
            var wellUnits = 0;
            var nw = null;
            var r, known, s, rub, liq, mp, outp, interest;
            for (r = 1; r <= period; r++) {
                known = this._known(d, r);
                s = this._season(known, r);
                interest = cash < 0 ? C.OVERDRAFT * (-cash) : 0;
                cash = cash + s.margin - s.capex + s.sale - interest;
                s.interest = interest;
                s.cash = cash;
                minCash = Math.min(minCash, cash);
                wellUnits += s.well;
                seasons.push(s);
                rub = this._rubric(known, r);
                liq = 5 * this._clamp01((cash - C.CASH_LO) / (C.CASH_HI - C.CASH_LO));
                if (r < 4) {
                    mp = 6 * this._clamp01(s.margin / C.MARGIN_FULL);
                    outp = mp + liq;
                } else {
                    nw = this._netWorth(known, cash);
                    mp = 5 * this._clamp01(s.margin / C.MARGIN_FULL);
                    outp = mp + 6 * this._clamp01((nw - C.NW_LO) / (C.NW_HI - C.NW_LO));
                }
                rounds.push({ period: r, rub: rub, outp: outp, pts: rub + outp, verdictKey: this._verdict(known, r, minCash) });
            }
            var last = seasons[seasons.length - 1];
            ds.rounds = rounds;
            ds.seasons = seasons;
            ds.cash = cash;
            ds.minCash = minCash;
            ds.wellUnits = wellUnits;
            ds.netWorth = nw;
            var score = this._composite(ds);
            ds.capKey = this._capKey(ds);
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                margin: last.margin,
                cash: cash,
                delivery: Math.round(last.I * 100),
                waterMet: Math.round(last.W * 100),
                yieldHa: Math.round(last.yld * 10) / 10,
                score: score,
                overallScore: score
            };
        }

        _known(d, r) {
            var out = {};
            var k;
            for (k = 1; k <= r; k++) { if (d['round' + k]) { out['round' + k] = d['round' + k]; } }
            return out;
        }

        _clamp01(x) {
            return Math.max(0, Math.min(1, x));
        }

        _clamp(x, a, b) {
            return Math.max(a, Math.min(b, x));
        }

        _fy(v, w) {
            return Math.max(C.FLOOR, 1 - C.SLOPE[v] * (1 - w));
        }

        _season(dec, q) {
            var r1 = dec.round1;
            var r2 = (q >= 2) ? dec.round2 : null;
            var r3 = (q >= 3) ? dec.round3 : null;
            var r4 = (q >= 4) ? dec.round4 : null;
            var mix = r3 ? r3.mix : r1.mix;
            var ts = C.TOLSHARE[mix];
            var drip = 0;
            var leyRejected = false;
            if (r2) {
                if (r2.capex === 'drip') { drip += C.DRIP_HA; }
                if (r2.capex === 'ley' && r2.water !== 'well' && q >= 3) { drip += C.DRIP_HA; }
                if (r2.capex === 'ley' && r2.water === 'well' && q === 3) { leyRejected = true; }
            }
            if (r3 && r3.capex === 'drip') { drip = Math.min(200, drip + C.DRIP_HA); }
            var res = !!(r3 && r3.capex === 'res');
            var I = C.DELIV[q - 1];
            var bonus = (res ? C.RES_BONUS : 0) + (r4 ? (r4.shares === 'buy' ? C.SHARES_BONUS : (r4.shares === 'sell' ? -C.SHARES_BONUS : 0)) : 0);
            var fallow = (q === 2 && r2.water === 'fallow') ? C.FALLOW_HA : 0;
            var planted = C.HA - fallow;
            var dripP = Math.min(drip, planted);
            var need = dripP * C.DRIP_REQ + (planted - dripP) * 1.0;
            var avail = (I + bonus) * C.HA;
            var well = 0;
            if (q === 2 && r2.water === 'well') {
                well = this._clamp(need - avail, 0, C.WELL_MAX * C.HA);
                avail += well;
            }
            var W = need > 0 ? Math.min(1.0, avail / need) : 1.0;
            var H = C.HEAT[q - 1];
            var yt = C.POT.trad * this._fy('trad', W) * H.trad;
            var yd = C.POT.tol * this._fy('tol', W) * H.tol;
            var yld = (1 - ts) * yt + ts * yd;
            var revM = planted * yld * C.PRICE;
            var costM = planted * (C.COST_HA + ts * C.TOL_SEED) + fallow * C.FALLOW_COST + C.FIXED + well * C.WELL_COST;
            var sha = (q <= 3) ? C.LEASE[r1.lease] : C.LEASE[r4.lease];
            var setup = 0;
            if (q === 1) { setup = sha * C.SETUP; }
            if (q === 4) { setup = Math.max(0, sha - C.LEASE[r1.lease]) * C.SETUP; }
            var SF = C.SOUTH[q - 1];
            var ys = (1 - ts) * C.POT.trad * SF.trad + ts * C.POT.tol * SF.tol;
            var revS = sha * ys * C.PRICE;
            var costS = sha * (C.SOUTH_COST + ts * C.TOL_SEED + C.RENT) + setup;
            var ins = [r1.ins, r2 ? r2.ins : null, r3 ? r3.ins : null, r4 ? r4.ins : null][q - 1];
            var prem = C.PREM[ins];
            if (q === 2) { prem *= (r1.ins !== 'none' ? C.RENEW2 : C.NEW2); }
            else { prem *= C.PMULT[q - 1]; }
            var pay = 0;
            if (ins !== 'none') { pay = C.SUM * Math.min(1.0, Math.max(0.0, (C.TRIG[ins] - I) / C.SPAN)); }
            var margin = revM + revS - costM - costS - prem + pay;
            var capex = 0, sale = 0;
            if (q === 2 && r2.capex === 'drip') { capex += C.DRIP_CAPEX; }
            if (q === 2 && r2.capex === 'ley') { capex += C.LEY_FEE; }
            if (q === 3 && r2.capex === 'ley' && r2.water !== 'well') { capex += C.LEY_NET - C.LEY_FEE; }
            if (q === 3 && r3.capex === 'drip') { capex += C.DRIP_CAPEX; }
            if (q === 3 && r3.capex === 'res') { capex += C.RES_CAPEX; }
            if (q === 4 && r4.shares === 'buy') { capex += C.SHARES_PRICE; }
            if (q === 4 && r4.shares === 'sell') { sale += C.SHARES_PRICE; }
            return {
                q: q, I: I, W: W, ts: ts, yld: yld, ys: ys, planted: planted, fallow: fallow, drip: drip, res: res, well: well, sha: sha,
                prem: prem, pay: pay, revenue: revM + revS, cost: costM + costS, margin: margin, capex: capex, sale: sale, leyRejected: leyRejected
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            if (r === 1) { return P.var1[dec.round1.mix] + P.lease1[dec.round1.lease] + P.ins1[dec.round1.ins]; }
            if (r === 2) { return P.capex2[dec.round2.capex] + P.water2[dec.round2.water] + P.ins2[dec.round2.ins]; }
            if (r === 3) { return P.capex3[dec.round3.capex] + P.var3[dec.round3.mix] + P.ins3[dec.round3.ins]; }
            return P.lease4[dec.round4.lease] + P.shares4[dec.round4.shares] + P.ins4[dec.round4.ins];
        }

        _netWorth(dec, cash) {
            var nw = cash - C.CASH0;
            var r2 = dec.round2, r3 = dec.round3, r4 = dec.round4;
            if (r2.capex === 'drip') { nw += C.DRIP_CAPEX * C.RESID.drip; }
            if (r2.capex === 'ley' && r2.water !== 'well') { nw += C.DRIP_CAPEX * C.RESID.drip; }
            if (r3.capex === 'drip') { nw += C.DRIP_CAPEX * C.RESID.drip; }
            if (r3.capex === 'res') { nw += C.RES_CAPEX * C.RESID.res; }
            if (r4.shares === 'buy') { nw += C.SHARES_VALUE; }
            if (r4.shares === 'sell') { nw -= C.SHARES_VALUE; }
            return nw;
        }

        _verdict(dec, r, minCash) {
            if (r === 1) {
                var r1 = dec.round1;
                if (r1.mix === 'trad') { return 'mono'; }
                if (r1.ins === 'none') { return 'bare'; }
                if (r1.lease === 'none') { return 'oneplace'; }
                return 'ok';
            }
            if (r === 2) {
                var r2 = dec.round2;
                if (r2.water === 'well') { return 'well'; }
                if (r2.capex === 'none') { return 'wait'; }
                if (r2.water === 'all') { return 'spread'; }
                if (r2.ins === 'none') { return 'bare'; }
                return 'ok';
            }
            if (r === 3) {
                var r3 = dec.round3;
                if (r3.capex === 'none') { return 'stop'; }
                if (r3.ins === 'broad') { return 'chase'; }
                if (r3.mix === 'trad') { return 'mono'; }
                return 'ok';
            }
            var r4 = dec.round4;
            if (minCash < -C.LINE) { return 'squeeze'; }
            if (r4.shares === 'sell') { return 'sellwater'; }
            if (r4.lease === 'none') { return 'retreat'; }
            return 'ok';
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        _wellCap(ds) {
            return Math.max(C.CAP_FLOOR, C.WELL_CAP - C.WELL_K * ((ds && ds.wellUnits) || 0));
        }

        _liqCap(ds) {
            var mc = (ds && typeof ds.minCash === 'number') ? ds.minCash : C.CASH0;
            return Math.max(C.CAP_FLOOR, C.LIQ_CAP - (-mc - C.LINE) / C.LIQ_K);
        }

        _cap(ds) {
            var cap = 100;
            var wu = (ds && ds.wellUnits) || 0;
            var mc = (ds && typeof ds.minCash === 'number') ? ds.minCash : C.CASH0;
            if (wu > 0) { cap = Math.min(cap, this._wellCap(ds)); }
            if (mc < -C.LINE) { cap = Math.min(cap, this._liqCap(ds)); }
            return cap;
        }

        _total(ds) {
            var rounds = (ds && ds.rounds) || [];
            var total = 0;
            var i;
            for (i = 0; i < rounds.length; i++) { total += rounds[i].pts; }
            return total;
        }

        _capKey(ds) {
            var total = this._total(ds);
            var cap = this._cap(ds);
            if (total <= cap) { return null; }
            var wu = (ds && ds.wellUnits) || 0;
            if (wu > 0 && cap === this._wellCap(ds)) { return 'cap_well'; }
            return 'cap_liq';
        }

        _composite(ds) {
            var total = Math.min(this._cap(ds), this._total(ds));
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('marginDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.seasons) || [];
                return ss.length ? self._fmtM(ss[ss.length - 1].margin) : '—';
            });
            uiManager.bind('cashDisplay', 'domainState', function(ds) {
                return self._fmtM((ds && typeof ds.cash === 'number') ? ds.cash : C.CASH0);
            });
            uiManager.bind('delivDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.seasons) || [];
                return ss.length ? String(Math.round(ss[ss.length - 1].I * 100)) + '%' : '—';
            });
            uiManager.bind('waterDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.seasons) || [];
                return ss.length ? String(Math.round(ss[ss.length - 1].W * 100)) + '%' : '—';
            });
            uiManager.bind('yieldDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.seasons) || [];
                return ss.length ? self._fmt1(ss[ss.length - 1].yld) : '—';
            });
            uiManager.bind('dripDisplay', 'domainState', function(ds) {
                var ss = (ds && ds.seasons) || [];
                return ss.length ? String(ss[ss.length - 1].drip) : '0';
            });
        }

        getChartConfig() {
            var t = this._t.bind(this);
            var sp = t('s_short');
            return {
                marginChart: {
                    type: 'bar',
                    data: {
                        labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                        datasets: [{ label: t('chart_dataset'), data: [0, 0, 0, 0], backgroundColor: ['#3d6b35', '#9a5a17', '#b8471f', '#2f5f7a'], borderWidth: 0 }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { ticks: { color: '#33412f' } }, x: { ticks: { color: '#33412f' } } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var ss = ds.seasons || [];
            var hist = ds.scoreHistory || [];
            var data = [0, 0, 0, 0];
            var sp = this._t('s_short');
            var i;
            for (i = 0; i < ss.length && i < 4; i++) { data[i] = Math.round(ss[i].margin); }
            return {
                marginChart: {
                    labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                    datasets: [{ data: data, label: this._t('chart_dataset') + (hist.length ? ' · ' + sp + hist.length : '') }]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundPoints', label: 'Points', i18nKey: 'col_points' },
                { key: 'results.margin', label: 'Season margin', i18nKey: 'col_margin', formatter: function(v) { return self._fmtM(v); } },
                { key: 'results.cash', label: 'Cash', i18nKey: 'col_cash', formatter: function(v) { return self._fmtM(v); } },
                { key: 'results.delivery', label: 'Canal delivery (%)', i18nKey: 'col_deliv' },
                { key: 'results.waterMet', label: 'Water met (%)', i18nKey: 'col_water' },
                { key: 'results.yieldHa', label: 'Yield (t/ha)', i18nKey: 'col_yield' },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ss = ds.seasons || [];
            var hist = ds.scoreHistory || [];
            var dec = ds.dec || {};
            var composite = this._composite(ds);
            var performance = 'Beginner';
            if (composite >= 55) { performance = 'Good'; }
            if (composite >= 75) { performance = 'Excellent'; }
            var prem = 0, pay = 0, i;
            for (i = 0; i < ss.length; i++) { prem += ss[i].prem; pay += ss[i].pay; }
            var insights = [];
            var r1 = dec.round1 || {};
            var r2 = dec.round2 || {};
            var r3 = dec.round3 || {};
            insights.push((r1.mix === 'trad' || r3.mix === 'trad') ? this._t('insight_var_mono') : this._t('insight_var_ok'));
            insights.push(((r1.ins === 'none' && r2.ins && r2.ins !== 'none') || r3.ins === 'broad') ? this._t('insight_ins_late') : this._t('insight_ins_ok'));
            insights.push((r2.capex === 'none' && r3.capex === 'none') ? this._t('insight_capex_none') : this._t('insight_capex_ok'));
            insights.push((ds.wellUnits || 0) > 0 ? this._t('insight_water_well') : this._t('insight_water_ok'));
            insights.push(this._t('insight_next'));
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                cash: ds.cash,
                minCash: ds.minCash,
                netWorth: ds.netWorth,
                premiums: prem,
                payouts: pay,
                rounds: hist.length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
